<?php
require 'includes/auth.php'; $id=(int)($_GET['id']??0);[$bf,$bp]=branch_filter_sql('s');$stmt=$pdo->prepare("SELECT s.*,b.branch_name FROM sales s JOIN branches b ON b.id=s.branch_id WHERE s.id=?".$bf);$stmt->execute(array_merge([$id],$bp));$sale=$stmt->fetch();if(!$sale){http_response_code(404);exit('Sale not found or access denied.');}
$stmt=$pdo->prepare("SELECT si.*,p.product_name FROM sale_items si JOIN products p ON p.id=si.product_id WHERE si.sale_id=?");$stmt->execute([$id]);$items=$stmt->fetchAll();$page_title='Sale Details';require 'includes/header.php';?><h1>Sale #<?=$sale['id']?></h1><section class="panel"><p><b>Branch:</b> <?=h($sale['branch_name'])?> · <b>Date:</b> <?=h($sale['sold_at'])?> · <b>Customer:</b> <?=h($sale['customer_name'])?></p><div class="table-wrap"><table><tr><th>Product</th><th>Qty</th><th>Unit price</th><th>Subtotal</th></tr><?php foreach($items as $i):?><tr><td><?=h($i['product_name'])?></td><td><?=$i['quantity']?></td><td>₱<?=number_format($i['unit_price'],2)?></td><td>₱<?=number_format($i['line_total'],2)?></td></tr><?php endforeach;?></table></div><h2>Total: ₱<?=number_format($sale['total_amount'],2)?></h2><button class="btn" onclick="window.print()">Print details</button></section><?php require 'includes/footer.php'; ?>
